INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('free-the-final-stroke-the-first-volume','Free! the Final Stroke: The First Volume','劇場版 Free!–the Final Stroke– 前編',2021,8,'Summer 2021','Movie','Finished','https://media.kitsu.app/anime/42357/poster_image/medium-9b65eb1a4aeb4c3e450e13fdc8b714c1.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/107203-ia50mzq59gdd.jpg','#ff3d8b','Theatrical follow-up to Free! Dive to the Future. As representatives of Japan, Haruka, Rin, and Ikuya are heading to Sidney to participate in the Swimming World Cup. They will finally compete with world class athletes but can they survive these games? This is the climax of the “Free!” series from Kyoto Animation. (Source: Crunchyroll)',NULL,'["Free! the Final Stroke: The Second Volume (2022)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":42357,"anilist":107203,"mal":38400}',NULL,NULL,1,datetime('now'),'free the final stroke the first volume 劇場版 free the final stroke 前編 movie finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('rec','Rec','レック',2006,7.3,'Winter 2006','TV','Finished','https://media.kitsu.app/anime/poster_images/644/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/710-27R6oM7rWdIV.jpg','#a24bff','Fumihiko Matsumaru is an average salaryman with no girlfriend. He invited his colleague Miss Tanaka to a movie but was stood up. Right at the time he was about to toss tickets into a trash can, a cute girl appeared and asked him not to waste those two tickets. After movie and dinner, he escorted her home and found they live in the same neighborhood, yet unfortunately her apartment caught on fire hours later. Having nowhere else to stay, rookie seiyuu Aka Onda moved to Matsumaru''s place, and the two had started a "more than friend but not yet lovers" relationship under the same roof while keeping this secret from their employers. (Source: ANN)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":644,"anilist":710,"mal":710}',NULL,NULL,9,datetime('now'),'rec レック tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('sk8-the-infinity-extra-part','SK8 the Infinity EXTRA PART','SK∞ エスケーエイト EXTRA PART',2025,8.1,'Winter 2025','TV','Finished','https://media.kitsu.app/anime/44870/poster_image/medium-937042bd81a58c0b6a33e50773a701de.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx136381-t6c5rfKjnqqd.jpg','#2f7bff','Original video animation for SK∞ (Sk8 the Infinity). Four slice-of-life omnibus stories. - "The Rain and a Cat, Soda Ice Cream from the Convenience Store" ("Ame to Neko Conbini Ice Soda Aji") — One Sunday, Reki, Langa, and Miya head out to the skatepark as usual when a squall suddenly hits them. They head back to Reki’s place and start playing Karuta, a Japanese card game they find!? - "Becoming Really Serious About Things" ("Maji de Maji ni Nareru Koto") — In the past, Sakurayashiki and Nanjo had spent their high school days in relative obscurity. These two always had butt heads and competed, but what lies ahead for them from all this competition? - "Morning Routine" — This story unravels the mystery surrounding Ainosuke and Kikuchi’s everyday life. It closes in on their secret moments, crossovers, and a moment beyond that draws closer. - "Hiromi, Do Your Best!" ("Ganbare Hiromi-chan!") — Shadow is an anti-hero at night, but this is his three-part slice-of-life flash story highlighting his noble and kind personality as he works hard at a flower shop during the day. (Source: Aniplex USA) Premiered in theaters on 01/24/2025. The home video was released on 03/19/2025.',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":44870,"anilist":136381,"mal":49363}',NULL,NULL,1,datetime('now'),'sk8 the infinity extra part sk エスケーエイト extra part tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('girly-air-force','Girly Air Force','ガーリー・エアフォース',2019,6,'Winter 2019','TV','Finished','https://media.kitsu.app/anime/poster_images/41375/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/101930-9eGb3psP0FX4.jpg','#ff3d8b','Mysterious flying creatures called Zai suddenly appear and overwhelm all of mankind''s aerial combat forces. To fight them, mankind modifies existing aircraft frames to create mechanized soldiers called "Daughters," which are operated by automated piloting mechanisms called "Anima" that have the appearance of human girls. The story begins when Narutani Kei, a boy who yearns to take to the skies, encounters a shining red aircraft and its pilot, an Anima named Gripen who has been named mankind''s trump card. (Source: Crunchyroll)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":41375,"anilist":101930,"mal":37998}',NULL,NULL,12,datetime('now'),'girly air force カ ーリー エアフォース tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
