INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('queens-blade-the-exiled-virgin','Queen''s Blade: The Exiled Virgin','クイーンズブレイド 流浪の戦士',2009,5.9,'Spring 2009','TV','Finished','https://media.kitsu.app/anime/poster_images/7762/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx4719-je2iLM7t0jsd.jpg','#ff3d8b','In a land where a queen is chosen every few years solely by winning a tournament, there can be no short supply of formidable opponents. For one woman warrior however, an early defeat clearly shows her that she is lacking in experience though she may be bountiful in body. Fortunately, while defeat could spell one''s doom, her life is saved by a powerful stranger. But unfortunately for this savior, less-than-pure motives and shrewd family members mean her reward is a prison cell. Her release is prompt when the unseasoned warrior she saved, tired of her current lifestyle of nobility, sets off to prove herself. (Source: Media Blasters)',NULL,'["Queen''s Blade 2: The Evil Eye (2009)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":7762,"anilist":4719,"mal":4719}',NULL,NULL,12,datetime('now'),'queen s blade the exiled virgin クイーンス フ レイト 流浪の戦士 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=exclud