INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('nekopara-ova','Nekopara OVA','ネコぱらOVA',2017,6.9,'Fall 2017','TV','Finished','https://media.kitsu.app/anime/poster_images/13121/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/99939-kDhj9oc1G79o.jpg','#ff9420','What''s NEKOPARA? Why, it''s a cat paradise! Kashou Minazuki, the son of a long line of Japanese confection makers moved out to open his own shop "La Soleil" as a patisserie. But upon moving out, hidden amongst his things were two of the catgirls ("neko"), Chocola and Vanilla, that the family had been raising. When he tried to send them back, they begged and pleaded until he gave in and now they''ve opened La Soleil together. With two nekos who really, REALLY love their master trying their very best and occasionally failing -- a heartful comedy opens for business! (Source: Official Website)',NULL,'["Nekopara OVA Extra (2018)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":13121,"anilist":99939,"mal":34658}',NULL,NULL,1,datetime('now'),'nekopara ova ネコは らova tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_s