INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('dragon-quest-the-adventure-of-dai','Dragon Quest: The Adventure of Dai','ドラゴンクエスト ダイの大冒険',2020,7.6,'Fall 2020','TV','Finished','https://media.kitsu.app/anime/poster_images/42900/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/114099-4YWtPpmPQyJb.jpg','#2ee6a8','After the defeat of the demon lord Hadlar, all of the monsters were unleashed from his evil will and moved to the island of Delmurin to live in peace. Dai is the only human living on the island. Having been raised by the kindly monster Brass, Dai''s dream is to grow up to be a hero. He gets to become one when Hadlar is resurrected and the previous hero, Avan, comes to train Dai to help in the battle. But Hadlar, announcing that he now works for an even more powerful demon lord, comes to kill Avan. To save his students, Avan uses a Self-Sacrifice spell to attack, but is unable to defeat Hadlar. When it seems that Dai and Avan''s other student Pop are doomed, a mark appears on Dai''s forehead and he suddenly gains super powers and is able to fend off Hadlar. The two students then go off on a journey to avenge Avan and bring peace back to the world. (Source: Anime News Network)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":42900,"anilist":114099,"mal":40906}',NULL,NULL,100,datetime('now'),'dragon quest the adventure of dai ト ラコ ンクエスト タ イの大冒険 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sc