INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('sonic-x','Sonic X','ソニックX',2003,6.3,'Spring 2003','TV','Finished','https://media.kitsu.app/anime/1633/poster_image/medium-f62f3631736007428a90139df3c78d93.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/1816-Kht0BR1Ft5An.jpg','#8b5cf6','Back on Sonic''s home planet, Eggman has collected all 7 of the Chaos Emeralds, and is about to have absolute power when Sonic interferes, causing an explosion that sends everyone from their world to Earth. Sonic and his friends team up with 12 year old Christopher Thorndyke to collect all the Chaos Emeralds and defeat the evil Dr. Eggman. (Source: ANN)',NULL,'["Sonic X: The Metarex Saga (2005)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":1633,"anilist":1816,"mal":1816}',NULL,NULL,78,datetime('now'),'sonic x ソニックx tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('the-hill-dyed-rose-madder','The Hill Dyed Rose Madder','あかね色に染まる坂',2008,6.3,'Fall 2008','TV','Finished','https://media.kitsu.app/anime/poster_images/3772/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/4744-OYmw5Jl4jZLg.jpg','#ff9420','Yuuhi Katagiri is not your average girl – she''s the treasured daughter of the Katagiri family. She''s generally kept under strict supervision, but one day ends up walking home from school on her own. This proves to be instant trouble when a group of boys start harassing her. Junichi Nagase, who was on his way home from a convenience store, sees the troubled Yuuhi and comes to her rescue. One of the boys recognized Junichi as the famed "Geno Killer" and they dash off. Yuuhi thanks Junichi and when she asked for his name, he just waves and leaves. Of course, he regrets trying to act cool in front of the beautiful girl right away, wishing he asked her name. The following day, a transfer student joins Junichi''s class – it''s Yuuhi! She calls Junichi out as the "Geno Killer", the only name she remembers him by, and rumors about the two spread quickly. Matters are made worse when Junichi kisses Yuuhi due to a misunderstanding. And on top of all that, it turns out that Junichi is Yuuhi''s fiancé! Yuuhi doesn''t see Junichi as someone worthy. But, she could not go against her father''s wishes. The only thing that Yuuhi can do is live with Junichi in the house he shares with his little sister Minato, and prove that Junichi is not worthy to be her husband. Will she succeed in proving his unworthiness, or will she fall in love on the way?',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":3772,"anilist":4744,"mal":4744}',NULL,NULL,12,datetime('now'),'the hill dyed rose madder あかね色に染まる坂 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('fragtime','Fragtime','フラグタイム',2019,6.7,'Fall 2019','TV','Finished','https://media.kitsu.app/anime/poster_images/42195/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/108487-8iPtV6KbPIks.jpg','#ffc247','What would you do if you could stop time? Moritani for one is using her unusual ability to stop time for three minutes a day to observe the people around her. One day, she chooses to "observe" class idol Murakami''s panties—only to find herself in a very compromising situation when her classmate turns out to be immune to her power. (Source: Yuri Project)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":42195,"anilist":108487,"mal":39545}',NULL,NULL,1,datetime('now'),'fragtime フラク タイム tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('haruka-nogizakas-secret','Haruka Nogizaka''s Secret','乃木坂春香の秘密',2008,7.1,'Summer 2008','TV','Finished','https://media.kitsu.app/anime/poster_images/3032/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/3467-nmhOnNrwEA4y.jpg','#3b82ff','Hakujo Academy is a private high school with a student body filled with elite students. At the top of this list is the beautiful Haruka Nogizaka, an intelligent and wealthy girl who comes from a prestigious family, and is by far the most idolized girl at school. Her popularity is so great that her classmates occasionally give her French nicknames to further express their infatuation. Yuuto Ayase is a timid boy who has the unbelievable luck of sitting in class with Haruka every day. Like many others, he admires her from a distance, never even dreaming of approaching her. But with a sudden twist of fate, Yuuto''s random visit to the school library brings Haruka''s darkest secret to light, one which could potentially destroy her current reputation of elegance. As it turns out, the school''s most beloved princess is actually a huge otaku. This revelation marks the beginning of a beautiful friendship between these two classmates.',NULL,'["Haruka Nogizaka''s Secret: Purezza (2009)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":3032,"anilist":3467,"mal":3467}',NULL,NULL,12,datetime('now'),'haruka nogizaka s secret 乃木坂春香の秘密 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('hanasaku-iroha-the-movie-home-sweet-home','Hanasaku Iroha the Movie ~ HOME SWEET HOME ~','花咲くいろは HOME SWEET HOME',2013,7.9,'Spring 2013','Movie','Finished','https://media.kitsu.app/anime/poster_images/7090/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/14175-GFS3RVamFPFR.jpg','#ff3d8b','In the days before the Bonbori Festival, Ohana''s friend Yuina comes to Kissuiso for training. While cleaning up after her, Ohana discovers a logbook kept by Beans from when her mother, Satsuki, was still a youth at Kissuisso. Through the logbook, Ohana catches a glimpse of her mother''s struggles, and realizes that maybe the two of them aren''t so different after all. Meanwhile, the rest of the inn staff are caught up in dealing with a blackout.',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":7090,"anilist":14175,"mal":14175}',NULL,NULL,1,datetime('now'),'hanasaku iroha the movie home sweet home 花咲くいろは home sweet home movie finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;

