INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('link-click-episode-5#1','link-click-episode-5',1,'Episode 1','22:00',1320,'','','[]',NULL,'306162');
