INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('to-love-ru-darkness-2nd-ova#1','to-love-ru-darkness-2nd-ova',1,'Volume 7','22:00',1320,'','Ghost Story: As Rito prepares to sleep, Nemesis sneaks into his room and wants him to tell her a ghost story. Nemesis begs Rito until Momo intervenes. She volunteers hoping that Nemesis would leave afterwards. As Nemesis and Rito listen to Momo''s ghost story, Nemesis criticizes it. She demonstrates her modification by using candlewax to molest Rito. Momo fights back with her own seduction. The fighting wakes Mikan up. When Mikan checks on Rito, Nemesis escapes in time to give Mikan the wrong picture. As Mikan disciplines Rito and Momo, Nemesis notes to be careful of Mikan. Clinic: Mikan talks with Yami and notices her uneasiness with Tearju. As Mikan discusses it with Rito, Momo receives a call that Mikado needs extra help at her clinic. Knowing that Tearju lives with Mikado, Mikan accepts hoping to get Yami interact with Tearju. Momo also gets Rito to participate by turning him into Riko. Although Riko gets molested by a patient and needs Yami to intervene, the rest of the day goes well. Afterwards, Mikado finds Tearju missing after heading to the basement. Yami goes to search and drags Riko along. As they head down the stairs, Riko encourages Yami to reunite with Tearju but Yami declines. She confronts Riko but quietly thanks her. They suddenly hear Tearju scream and find a medical robot molesting her. She accidentally tripped and activated it. The robot spots Riko and Yami and performs procedures by stripping them and applying bandages. Yami demands to Tearju to escape, but Tearju refuses, choosing not to leave her daughter behind. As the robot attempts to cast gauze bandages on Tearju and Riko, Yami destroys it. She also receives an unwanted surprise from Riko.','[]','2016-01-04','179863');
