INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('queens-blade-the-exiled-virgin#1','queens-blade-the-exiled-virgin',1,'High Spirits: The Vagrant Warrior','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/108146/original.jpg','Under the new Queens rule, free trade has improved the lives of the citizens. But there are those who live for the battle. A new set of warriors and old grudges have returned for the rebellion.','[]','2012-04-03','108146');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('queens-blade-the-exiled-virgin#2','queens-blade-the-exiled-virgin',2,'Ambitious Undertaking: Warrior Priestess','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/108147/original.jpg','While performing her duties as an Inquisitor, Sigui is asked by the town people to listen to their problems. The perceived arrogance of one confession leads her to declaring that person a heretic. All heretics must be burned.','[]','2012-04-10','108147');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('queens-blade-the-exiled-virgin#3','queens-blade-the-exiled-virgin',3,'Charm Attack: Veteran Mercenary','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/108148/original.jpg','Annelotte has traveled to the jungle to find the source of the fog plaguing the townsfolk. When she befriends a local tribe, they believe Annelotte to be the Knight of BlackLuna’s prophecy. But it seems key details were left out…','[]','2012-04-17','108148');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('queens-blade-the-exiled-virgin#4','queens-blade-the-exiled-virgin',4,'Rivalry: Thundercloud General','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/108149/original.jpg','While performing her duties as an Inquisitor, Sigui is asked by the town people to listen to their problems. The perceived arrogance of one confession leads her to declaring that person a heretic. All heretics must be burned','[]','2012-04-24','108149');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('queens-blade-the-exiled-virgin#5','queens-blade-the-exiled-virgin',5,'Resurrected Curse: Ancient Princess','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/108150/original.jpg','While trying to sneak into the castle, Yuit and Annelotte have come across a colosseum underneath the castle. In exchange for Annelotte entering the fights and winning, her backer will tell them where to find Ymir. An easy agreement until she has to fight the dragon warrior, Branwen','[]','2012-05-01','108150');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('queens-blade-the-exiled-virgin#6','queens-blade-the-exiled-virgin',6,'Promise: Forest Keeper','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/108151/original.jpg','Annelotte finally confronts Mirim and her nearly invincible Hyper Vibration Armor, and in the middle of the fierce showdown, Captain Liliana''s flying pirate ship suddenly appears in the sky above.','[]','2012-05-08','108151');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('queens-blade-the-exiled-virgin#7','queens-blade-the-exiled-virgin',7,'Advent: Angel of Light','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/108152/original.jpg','Vante is captured by Liliana, and Annelotte and Yuit must sneak onboard her pirate ship to retrieve Vante. But they are not the only stowaways there.','[]','2012-05-15','108152');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('queens-blade-the-exiled-virgin#8','queens-blade-the-exiled-virgin',8,'Stealth: Assassin of the Fang','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/108153/original.jpg','Ymir recruits Summoner Aldra to join the queen''s army. Aldra summons two underworld demons, Belphe and Dogor, to aid in her fight, but they are more interested in finding some tasty humans to feed on.','[]','2012-05-22','108153');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('queens-blade-the-exiled-virgin#9','queens-blade-the-exiled-virgin',9,'The Arms Dealer and the Steel Princess','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/108154/original.jpg','Annelotte accidentally travels to a small village of orphaned children, where she meets the self-proclaimed "Samurai God" Izumi. Realizing that Annelotte is a stronger and more skilled fighter, Izumi asks Annelotte to teach her better swordsmanship. And not a moment too soon, for the underworld demons Belphe and Dogor just appear in their village to eat the children.','[]','2012-05-29','108154');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('queens-blade-the-exiled-virgin#10','queens-blade-the-exiled-virgin',10,'Enlightenment: Blow of the Dragon','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/108155/original.jpg','Annelotte and her band of rebels return to Gainos Castle with the intention of confronting the queen head-on, but Ymir has anticipated their arrival and set a dangerous trap for them.','[]','2012-06-05','108155');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('queens-blade-the-exiled-virgin#11','queens-blade-the-exiled-virgin',11,'Thunder: After the Death Battle','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/108156/original.jpg','Fierce battles rage across the castle as the forces of good clash with the forces of evil. Admist the climatic showdown, a sinster secret is revealed.','[]','2012-06-12','108156');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('queens-blade-the-exiled-virgin#12','queens-blade-the-exiled-virgin',12,'Final Destiny','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/108157/original.jpg','Annelotte finally comes face-to-face with Thundercloud Queen Claudette, and the fate of the continent will be decided by the one who emerges victorious.','[]','2012-06-19','108157');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('nekopara-ova#1','nekopara-ova',1,'Episode 1','60:00',3600,'','','[]',NULL,'208077');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-the-08th-ms-team#1','mobile-suit-gundam-the-08th-ms-team',1,'War for Two','24:00',1440,'','En route to his new assignment on Earth, Federation officer Shiro Amada comes across an ally battling a Zeon Zaku. Attempting a brave rescue in a Ball, he has a fateful encounter with the enemy pilot, Aina Sahalin.','[{"kind":"intro","label":"Opening","start":0,"end":91},{"kind":"outro","label":"Ending","start":1365,"end":1440}]','1996-01-25','1915');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-the-08th-ms-team#2','mobile-suit-gundam-the-08th-ms-team',2,'Gundams in the Jungle','24:00',1440,'','Shiro arrives at a jungle base in Southeast Asia to take command of the 08th MS Team. Ordered to sortie right away, he leads his team into battle, but struggles with combat in Earth''s unfamiliar gravity and in the dark of night.','[{"kind":"intro","label":"Opening","start":0,"end":91}]','1996-01-25','1916');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-the-08th-ms-team#3','mobile-suit-gundam-the-08th-ms-team',3,'The Time Limit on Trust','24:00',1440,'','In its second mission, the 08th MS Team is ordered to sweep the Zeon forces from a hilly area. However, the team''s advance is stalled by enemy fortifications. Shiro attempts to flank the enemy via a river frequented by guerrillas, but then...','[{"kind":"intro","label":"Opening","start":0,"end":90}]','1996-03-25','1917');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-the-08th-ms-team#4','mobile-suit-gundam-the-08th-ms-team',4,'The Demon Overhead','24:00',1440,'','Every team that Sanders has ever belonged to has been wiped out on its third mission, and now it''s the turn of the 08th MS Team. The worried Sanders asks Shiro to transfer him, but then Zeon''s new mobile armor Apsaras appears.','[{"kind":"intro","label":"Opening","start":0,"end":91}]','1996-10-25','1918');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-the-08th-ms-team#5','mobile-suit-gundam-the-08th-ms-team',5,'The Broken Order to Standby','24:00',1440,'','The musician Eledore learns that he will be making his major-label debut. In high spirits, he drags Michel along to a nearby village to celebrate. But when they reach the bar, the pair find gun-toting Zeon soldiers waiting for them.','[{"kind":"intro","label":"Opening","start":0,"end":91}]','1996-11-25','1919');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-the-08th-ms-team#6','mobile-suit-gundam-the-08th-ms-team',6,'Battle Line On the Burning Sand','24:00',1440,'','Having discovered the Apsaras''s testing ground, the 08th MS Team lie in wait for an ambush, preparing for the encounter with combat simulations. The team members'' frustrations mount as the Apsaras fails to appear, until they finally come to blows.','[{"kind":"intro","label":"Opening","start":0,"end":90}]','1996-12-18','1920');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-the-08th-ms-team#7','mobile-suit-gundam-the-08th-ms-team',7,'Reunion','24:00',1440,'','The Apsaras makes its escape, with Shiro''s Gundam clinging to its hull. When the malfunctioning mobile armor crashes in the snowy mountains, Shiro and Aina are reunited. They cooperate to survive in the frozen wasteland, but then rescuers arrive...','[{"kind":"intro","label":"Opening","start":0,"end":90}]','1997-10-25','1921');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-the-08th-ms-team#8','mobile-suit-gundam-the-08th-ms-team',8,'Duty and Ideals','24:00',1440,'','Shiro has returned safely from the mountains, but is now suspected of being a spy, and is confined to his quarters until a verdict is decided. Then Kiki''s village comes under Zeon attack, and Shiro must violate his orders to go to the rescue.','[{"kind":"intro","label":"Opening","start":0,"end":90}]','1997-12-28','1922');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-the-08th-ms-team#9','mobile-suit-gundam-the-08th-ms-team',9,'Front Line','24:00',1440,'','The Federation Forces, having learned that the Apsaras was created to destroy Jaburo, begin searching for the development base. Shiro and the 08th MS Team descend into enemy territory to aid the search, only to encounter retreating Zeons.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1366,"end":1440}]','1998-02-25','1923');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-the-08th-ms-team#10','mobile-suit-gundam-the-08th-ms-team',10,'The Shuddering Mountain, Part 1','24:00',1440,'','The Federation Forces begin their assault on the Apsaras development base. The 08th MS Team is assigned to escort a Guntank team into firing position, but Norris''s Gouf Custom swiftly dispatches two of the Guntanks. Can the team save the last one?','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1439,"end":1440}]','1998-07-25','1924');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-the-08th-ms-team#11','mobile-suit-gundam-the-08th-ms-team',11,'The Shuddering Mountain, Part 2','24:00',1440,'','The Apsaras cuts loose with its devastating mega particle cannon. As the Federation''s Colonel Ryer and Zeon''s Ginius Sakhalin escalate the fighting, Shiro and Aina transcend the division between the two sides to face their final challenge.','[{"kind":"intro","label":"Opening","start":0,"end":92},{"kind":"outro","label":"Ending","start":1343,"end":1416}]','1999-04-25','1925');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-the-08th-ms-team#12','mobile-suit-gundam-the-08th-ms-team',12,'Last Resort','24:00',1440,'','With the end of the war, Michel has retired from the Federation Forces, and he sets off with Kiki to find out whether Shiro and Aina are alive or dead. In the jungle, they are captured by a group of mysterious children, who give them shocking news.','[]','1999-07-25','1926');
