INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#1','sonic-x',1,'Enter the Supersonic Hero!','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163078/original.jpg','Sonic busts into Chaos Control to stop Eggman from using the Seven Chaos Emeralds and save his friends Cream and Cheese.He screws though and it sends Sonic, Knuckles, Amy, Tails, Cream and Cheese to another world!! Sonic is confused by his surroundings. People are stunned at seeing a Blue Hedgehog! They all try to catch him but Sonic''s to stubborn and quick for them. So anyway Sonic goes off and running from the police.He then encounters Sam Speed and the S-Team! Sam Speed trys to catch Sonic but he''s to quick for him! Now Sonic is even toying with them!Sam has no choice but to use his Nitro. Sonic is able to lose them though. Now Sonic jumps off a cliff looking at all the beautiful sights but something is below him....a pool! He falls in and starts drowning not able to get up! Luckily he is saved by Christopher ""Chris"" Thorndyke who is shocked that Sonic can talk so they become friends.','[]','2003-08-23','163078');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#2','sonic-x',2,'Infiltrate! Area 99','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163086/original.jpg','Sonic has unofficially taken residence at Chris'' house. Chris is a young boy, whose family is rich. While Chris and Sonic are watching TV, Chris'' grandfather, Chuck, walks into the room and discovers Sonic. Almost taken apart by Chuck, Sonic flies out of the way to the other side of the room. Sonic then hears on the TV that Cream and Cheese were found. Chuck sees this and agrees to help Sonic find his friends. Cream and Cheese have been taken to Area 99; a top-secret military base. It is very high security, so Chuck gives Sonic an infrared scope to find his way around. Sonic finds Cream and Cheese in a lab being tested. He breaks them out, but then the security cameras catch him and start firing their lasers at them. After the cameras'' lasers destroy about half of the base, Sonic hears a noise outside. It''s the tornado! Sonic bolts out the wall and lands on the Tornado, and they all fly back to Chris'' house to reunite.','[]','2003-09-13','163086');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#3','sonic-x',3,'Dr. Eggman''s Ambition','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163091/original.jpg','Knuckles and Amy are scouring the sewers trying to find a way out while Eggman hatches a giant robot named Missle Wrist and Knuckles'' is too stubborn to care about it. Can Sonic, Chris, Tails, Cream, and Cheese stop this horrible disaster?','[]','2003-09-20','163091');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#4','sonic-x',4,'Getting The Chaos Emerald!!','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163097/original.jpg','A Chaos Emerald is found so Chris is determined to get it before Eggman does to show Sonic that he can be a help. But what''s in store when Eggman hatches a giant bird robot?','[]','2003-09-27','163097');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#5','sonic-x',5,'Clash!! Sonic vs. Knuckles','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163102/original.jpg','Eggman tricks Knuckles by saying that Sonic was the one that sent them to the new world. Now Knuckles is more furious then ever to destroy Sonic, and they have an ultimate clash.....or is everything Eggman said just a fake?','[]','2003-10-04','163102');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#6','sonic-x',6,'Fierce Battle! School Wars','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163107/original.jpg','Being mad after losing three times, Eggman decides to make a robot named E-51 to go to Chris'' school and ruin it. But things turn around when E-51 forgets all about his mission and has fun with the kids!!','[]','2003-10-11','163107');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#7','sonic-x',7,'Giant Free For All! Chris'' House Party','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163115/original.jpg','Chris throws a home party inviting his teacher Stuart, his Mom''s brother Sam Speed, but Chaos Corrupts when Cream begins thinking about her mom...','[]','2003-10-18','163115');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#8','sonic-x',8,'Emergency Launch! X Tornado','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163120/original.jpg','Tails builds a X-Tornado 2 while meanwhile Eggman uses a Satellite to turn down all televisons. Tails finishes building it, and then Sonic, Tails, and Chris take it for a Spin to stop Eggman''s fortress, and his Satellite.','[]','2003-10-25','163120');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#9','sonic-x',9,'Amy on the Beach','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163125/original.jpg','Chris, Tails, Amy, Cream, and Cheese go to the beach, but Sonic stays behind and goes for a run. Amy has day dreams about Sonic on the beach, and decides to make a necklase for her hero, Sonic. Meanwhile Eggman hatches a mischevious plan to ruin the beach, and without Sonic what will they do? Luckily Sonic comes and fights Eggman''s huge robot, but almost gets hurt, and Amy isn''t too pleased......','[]','2003-11-01','163125');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#10','sonic-x',10,'Fierce Fight! Sonic Baseball Team','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163132/original.jpg','Tails finds another Chaos Emerald, but in order to get it Sonic and pals(including Tails) must win a very odd baseball game against Eggman and his robot''s. Or is Eggman just tricking them so he can get all the loot even if he doesn''t win?','[]','2003-11-08','163132');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#11','sonic-x',11,'The Beautiful, Mysterious Thief Rouge Arrives','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163135/original.jpg','A jewel theif is on the loose-Rouge The Bat. And she plans to steal the Chaos Emeralds by tricking the goverment, by working with them, and pretending to help infilitrate Eggman''s Fortress, when she really just plans to steal the Chaos Emerald.','[]','2003-11-15','163135');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#12','sonic-x',12,'Before the Attack on Eggman''s Base','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163142/original.jpg','The President of The United States says his plans to defeat Eggman, while Knuckles trys to sneak into Eggman''s base. Meanwhile Tails, Chris, Amy, and one of Chris'' friends, Francine find another Chaos Emerald but Eggman shows up with his giant Wind Robot, and blows them away!','[]','2003-11-22','163142');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#13','sonic-x',13,'After the Attack on Eggman''s Base','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163147/original.jpg','Rouge, Topaz, Knuckles, and the goverment break into Eggman''s base and try to infilitrate it while Sonic and pals try to infilitrate it as well, and get the Chaos Emerald back. But Eggman has a huge suprise in store for Sonic...','[]','2003-11-29','163147');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#14','sonic-x',14,'That''s What Friends Are For','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163155/original.jpg','After destroying Eggman''s base Sonic has become a huge celeberity and the President invites him and his friends to a party but Sonic has promised his new friend Helen that he''d take her to a mountain because her dad never did. Now the president is trying to catch Sonic and take him to the party and Sonic and Helen are on the run!!','[]','2003-12-06','163155');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#15','sonic-x',15,'Skirmish In The Sky','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163165/original.jpg','Ella decides to take Amy, Tails, Chris, Cream, and Cheese out to the mall, but they see the return of Eggman, and his new Egg Fortress. Eggman launches some missles to the City, and it''s up to Sonic to stop them. They end of defeating Eggman, and him and the Egg Carrier fall to the deep ocean....','[]','2003-12-13','163165');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#16','sonic-x',16,'Depths of Danger','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163175/original.jpg','Sonic, Tails, Cream, Cheese, and Chris discover that a Chaos Emerald is in the Ocean of a Motel, so they go on a vacation try to find a Chaos Emerald in the deep Ocean but it turns out that Eggman is under the sea, and ready to attack, trying to get the Chaos Emerald too.','[]','2004-01-17','163175');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#17','sonic-x',17,'The Adventures of Knuckles and Hawk','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163180/original.jpg','Knuckles has been traveling for days to reach a small town, to see his friend Hawk, and get another Chaos Emerald. They must prevent Rouge or The Fly Thief from getting it and Knux may even have to throw in some punches.','[]','2004-01-24','163180');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#18','sonic-x',18,'The Dam Scam','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163195/original.jpg','Sonic, Chris, and Tails attempt to destroy Dr. Eggman''s Egg Fort, but get the Tornado shot down and they get separated!! Now Tails, and Chris must stop some Damworkers from building a Dam that will block electricity, while Sonic must defeat Eggman''s Giant Robot Monkey that can become invisible!!','[]','2004-01-31','163195');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#19','sonic-x',19,'Sonic''s Scream Test','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163202/original.jpg','Chris'' mom is doing part of a play in an old castle. While Sonic is walking in the castle, all of the sudden, everything shakes all of the sudden. During the night when Lindsay is putting on her makeup, the mirror all of the sudden takes her alive. The gang goes about looking for her, when all of the sudden Ella is sucked into a wall. When trying to rescue her, Sonic and Tails are sucked in as well. Amy and Chris try and rescue everyone. They figure out that a stone has something to do with this.','[]','2004-02-07','163202');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#20','sonic-x',20,'Cruise Blues','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163208/original.jpg','After many weeks of looking for Chaos Emeralds, Nelson suggests that everyone takes a break and goes for a cruise on one of his spare yachts. However, the ship isn''t big enough for Sonic to run on, at all. Everyone is worried, so an airlift is called in to send Sonic away, but Tanaka is on it, and he has a group of elderly women on board. He says they will be their coaches, guiding them on how to relax, leaving Sonic on the ship, just as he tricks Tails into thinking the X Tornado is lonely, and lies to Amy that she is the cutest thing he''s ever seen (lol!). Just as the ship approaches the glaciers, the Egg Fort 2 launches for the first time with an attack.','[]','2004-02-14','163208');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#21','sonic-x',21,'Fast Friends','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163211/original.jpg','It''s the middle of the night. But Chris''s Uncle can care less. Sam would like to challenge the speedy blue demon to a speed match; which he''s not to interested in. He finally gives in to all the influences, and goes ahead, with the entire country watching this show down, as well as the president.','[]','2004-02-21','163211');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#22','sonic-x',22,'Little Chaos Lost','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163218/original.jpg','While exploring Tanaka''s mountainous homeland, Cream and Cheese decide to take a swim. However Cheese is carelessly swept away down the river by a strong current, and the gang has to find him. When they reach the spot where they find Cheese, it''s a beautiful, crisp lake inhabited by many chao that have been transported here as well. The gang begins to enjoy the company when unfortunately, Dr. Eggman is taking a hike too; and he plans to ruin the vacation!','[]','2004-02-28','163218');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#23','sonic-x',23,'Emerald Anniversary','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163224/original.jpg','Rouge and Topaz are ''hanging out'' when Rouge spots some beautiful jewelry in the store across the street, but Topaz blurts out ''Thief!'' just to anger Rouge. Then Nelson, Chris'' dad buys a expensive ring in the store, because it''s his anniversary with Lindsay, Chris'' mom. Meanwhile, at the Thorndyke''s Mansion, Sonic, Tails, Amy, Cream, and Cheese recieve a phone call from Nelson, telling them to go to his office. But Sonic gets a weird reaction from his Chaos Emerald that he''s holding, and it turns out that the ''ring'' is actually a Chaos Emerald! Knuckles sees the reaction and goes straight to help the gang. But in the shadows Eggman sees the reaction too and decides to jump in with his giant robot to steal the Chaos Emerald for himself!','[]','2004-03-06','163224');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#24','sonic-x',24,'How to Catch a Hedgehog','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163235/original.jpg','Eggman comes in to the area disturbing the peace, but he''s not match for blue. However, when Sonic is fighting, some sort of computer chip lands in Sonic''s ear, causing him to pick his ears for the rest of the day (which Amy hates!). When a remote is pressed, Sonic goes berserk, and then begins to run fast and uncontrollably into the desert. The gang has to come up with ways to stop him, with the assist from Knuckles and Sam, but to their luck, they all fail, and Sam is no help either. What will they do?','[]','2004-03-13','163235');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#25','sonic-x',25,'A Dastardly Deed','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163249/original.jpg','Now we''re on the wire. Six Chaos Emerald have been found, but Eggman has one, and plans to use his E-77 robot to seek out the last one. Meanwhile, Knuckles is looking for the Last Chaos Emerald too. He realizes that the only way for him, Sonic, Tails, Chris, Amy, Cream, and Cheese to get all the Chaos Emeralds is to team up with Eggman. So Knuckles visits the Thorndyke residance, but Sonic, Tails, Cream, Amy, and Cheese are out looking for the last Chaos Emereald as well, so Knuckles teams up with Chris to go to Eggman''s base and ask for a partnership. Eggman agrees, but he asks if he can hold the Chaos Emeralds that they have, and foolishly Knuckles agrees. Chris and Knuckles try to keep it a secret from Sonic, Tails, Amy, Cream, and Cheese though. Meanwhile, it turns out that Eggman tricked him, and he steals the Chaos Emeralds for himself...as E-77 is returning with the last Chaos Emerald....what will happen next?','[]','2004-03-20','163249');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#26','sonic-x',26,'Countdown to Chaos','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163261/original.jpg','A very sad episode indeed. After a trap set last set by Dr. Eggman, Chris is held captive in E-99 on the shores while Sonic is trying his hardest to defeat it and get Chris back. However, with the power of seven Chaos Emeralds, it''s not that easy. Sonic is bruised and beaten...badly. Chris can''t stand the sight of his hero beat up, and actually breaks himself free to grab the emeralds and jump in the water to help Sonic. Behold! Super Sonic rises out and destroys E-99, and then a blast of Chaos Control is released, as Station Square watches in awe.','[]','2004-03-27','163261');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#27','sonic-x',27,'A Messenger from a Meteor Shower','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163274/original.jpg','What has happened? Two huge islands formed on the shores of Station Square, one of them being Angel Island, which is falling! Chaos Control apparently brought Sonic''s world to Station Square, leaving Chris happy but Eggman to formulate a way to destroy the city. Next, Eggman is instructing his E-100 team to set out and destroy things. Even more terrible, Chaos is loose on Station Square streets reeking havoc! The beginning of the Sonic Adventure adaptation has begun!','[]','2004-09-18','163274');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#28','sonic-x',28,'The Spaceship Blue Typhoon','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163283/original.jpg','After a brief discussion with Chuck,Sonic &amp; Tails search for the Chaos Emeralds, Knuckles searches for the pieces of the Master Emerald, and Big &amp; Chris search for Froggy. Knuckles gets an image from the past. Sonic &amp; Tails encounters Eggman &amp; Chaos, who goes under another transformation, while finding a Chaos Emerald. Sonic beats Chaos and Eggman escapes in his Egg Carrier. Sonic &amp; Tails goes into the X Tornado and chases Eggman, but Eggman shoots down the X Tornado. Meanwhile, Amy runs into a small bird and they both get kidnapped by one of Eggman''s robots. Can Sonic rescue Amy?','[]','2004-09-25','163283');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#29','sonic-x',29,'The Water Planet Hydo','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163291/original.jpg','After Amy''s kidnapping, Sonic &amp; Tails head off in the X Tornado to rescue her. Meanwhile, Knuckles gains most of the Master Emerald pieces and gets another vision of the past. After the vision, Knuckles puts the pieces on the altar and discovers the remaining pieces are in the Egg Carrier. Big &amp; Chris manages to find Froggy, but gets stolen by E-102 Gamma and They sneak into the Egg Carrier. After Gamma''s success of getting Froggy, Eggman sends the other E-series into other places and orders Gamma to get the bird that''s with Amy. When Gamma confronts Amy, she persuades him to help her escape. Knuckles hitches a ride with Sonic &amp; Tails and battles the Egg Carrier. After getting through the weapons, they enter the Egg Carrier where dangers await them.','[]','2004-10-02','163291');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#30','sonic-x',30,'Heads Up, Tails!','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163294/original.jpg','It''s a battle on the Egg Carrier. Knuckles tries to get the last peices of the master emerald, Big and Chris need to get Froggy, and Sonic and Tails need to get Eggman. But when Chaos turns into Chaos 6 and captures Froggy, Big ,and Chris, It''s up to Sonic and Knuckles to set them free. When Eggman launches a missle to destroy Station Square, It''s all up to Tails to detonate it.','[]','2004-10-09','163294');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#31','sonic-x',31,'Revenge of the Robot','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163301/original.jpg','After the missle attack was prevented, E-102 Gamma deletes master obedience data and heads off. Meanwhile, Amy sets of to find Lilly''s brothers. Then, Sonic explores an ancient temple and gets a vision of the past. Then, he fights the Egg viper. Gamma frees Delta, Epsilon, and Zeta. But, Beta tries to destroy him. Can Gamma free Beta?','[]','2004-10-16','163301');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#32','sonic-x',32,'Flood Fight','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163304/original.jpg','It''s total chaos! Chaos absorbs the 7th Chaos Emerald and starts to destroy Station Square! Now with the Emeralds drained of their power, Sonic &amp; friends must use their friendship to power the Emeralds and Sonic changes to Super Sonic! Will Sonic be able to defeat the mystical sea monster known as Chaos?','[]','2004-10-23','163304');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#33','sonic-x',33,'Project: Shadow','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163312/original.jpg','After accidentally finding Prof. Gerald''s diary, Eggman breaks into the military searching for the ""Ultimate Creature"": Shadow. Thanks to the Egg Mobile, Eggman finds the console &amp; finds an unknown creature...','[]','2004-10-30','163312');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#34','sonic-x',34,'Shadow Knows','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163314/original.jpg','After Shadow steals one of the Chaos Emeralds, Sonic is blamed for the crime and finds himself on the run from the law. As he does so, he runs into Shadow, and realizes why he''s suddenly become a wanted criminal, because Sonic and Shadow look very much alike. As the two collide, Shadow reveals his ability to harness the power of the Chaos Emerald to use Chaos Control, which gives him an edge over Sonic.','[]','2004-11-06','163314');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#35','sonic-x',35,'Sonic''s Big Break','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163323/original.jpg','Under a new alliance, Shadow, Rouge, and Eggman carry out their latest plan. As Eggman launches an attack on Prison Island, Rouge breaks in to steal three Chaos Emeralds, and Shadow sneaks in to plant a bomb which will destroy the island. As Chris and Tanaka use a small boat to get to Prison Island, Tails and Amy arrive at the island in the X Tornado to rescue Sonic. When Amy accidently runs into Shadow, Eggman comes in to finish her off but Tails jumps in and fights with Eggman. Amy goes in and frees Sonic, who then finds Shadow. The two hedgehogs battle it out. However, problems arise. Rouge gets trapped in the compound, and Shadow, having another flashback of Maria, breaks away from the battle to go save her. When he gets there, Chris is there too, and pleads with Shadow because Sonic wound up taking the blame for his actions. With less than 10 seconds left before the bomb explodes, Shadow activates Chaos Control, enveloping Rouge and Chris in its energy. The bomb explodes, destroyi','[]','2004-11-13','163323');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#36','sonic-x',36,'Shadow World','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163334/original.jpg','Sonic, Tails, Knuckles &amp; Amy manage to break into Eggman''s base, undetected. At least they THINK they''ve entered undetected. Bokkun finds them &amp; calls on the Egg Golem! They board the space shuttle, but their adventure has just begun...','[]','2004-11-20','163334');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#37','sonic-x',37,'Robotnik''s Revenge','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163340/original.jpg','Sonic, Tails, Knuckles, Amy and Tanaka have arrived at the ARK, but when Robotnik, Rouge and Shadow programme the ARK on a path to oblivion, it''s Sonic The Hedgehog to the rescue in outer space!','[]','2004-11-27','163340');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#38','sonic-x',38,'Showdown in Space','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163359/original.jpg','As the clock ticks for Space Colony Arc''s crash, Sonic, Eggman, Bokkun, Dekkun, Knuckles, Tails, and Rouge try to get the Master Emerald to the power source, The Chaos emeralds. Meanwhile, Shadow is faced by Chris, who reminds him of Maria''s Wish, to help Mankind. As Sonic, Knuckles and the two robots reach the power source, a recreated temple of Chaos, a robot/organic beast attacks the crew, thinking of a way past, Shadow offers to distract the beast long enough to stop the colony. Will they succeed? Watch and find out!','[]','2004-12-04','163359');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#39','sonic-x',39,'Defective Detectives','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163377/original.jpg','The Chaotix Detectives made up of Vector the Crocodile, Espio the Chameleon, and Charmy the Bee have arrived in Station Square. Their goal is to find Cream for a specific reason, even when they think Sonic stole her. Meanwhile, Dr. Eggman rebuilds half the moon (after part of it was destroyed last episode) into the Eggmoon and claiming to Sonic that he has become reformed. Is this true? And will the others know why the Chaotix Detectives have come for Cream.','[]','2004-12-11','163377');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#40','sonic-x',40,'Sunblock Solution','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163384/original.jpg','When an eclipse from the newly-repaired moon blocks the sun, Station Square faces a risk of panic. Eggman steps in and creates an artificial sunlight orb to provide light through out the city. It seems like Eggman is truly doing some good. Unfortunately, Sonic dosen''t think so...','[]','2004-12-18','163384');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#41','sonic-x',41,'Eggman For President','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163390/original.jpg','After the success of the sunshine balls, Eggman then tries to execute the rest of his plan. Sonic explains how Eggman eggmoon is moving to block, meaning Eggman set up the eggmoon as part of his master plan. Eggman then captures the president, and as he starts to make his own money, Sonic and Tails crash the X-Tornado into the white house and explain what happen while Mr. Tanaka and Topaz move the eggmoon out of the suns path. Sonic then set up a trivia challenge and traps Eggman by hitting him on the head with a big metal pan, and Eggman is sent to jail.','[]','2005-01-22','163390');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#42','sonic-x',42,'A Date to Forget','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163396/original.jpg','Sonic is supposed to have a date with Amy, but he doesn''t show up. So instead, she has a date with Sam Speed. Meanwhile on Eggman''s old island base, Bokkun finds one of Prof. Gerald Robotnik''s other creations: Emerl &amp; tries to tell him to defeat Sonic. Bokkun opens the door, &amp; he &amp; Emerl walk to the tank. Sonic is trying to get to his date with Amy, but Bokkun stops him to free Eggman, Decoe &amp; Bocoe from jail with the new tank. Can Sonic stop Bokkun &amp; Emerl from freeing Eggman? Or will he be late for his date with Amy?','[]','2005-01-29','163396');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#43','sonic-x',43,'Mean Machines','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163410/original.jpg','','[]','2005-02-06','163410');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#44','sonic-x',44,'The Sewer Search','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163418/original.jpg','Stewart keeps a close eye on Eggman. Unfortunetly for him, Chris, Helen, Danny, Cream, Cheese, and Emerl stick with Stewart for the ride. When they are all captured by Eggman, they must try to find a way out, or at least figure a way to contact Sonic to help...','[]','2005-02-12','163418');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#45','sonic-x',45,'Prize Fights','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163430/original.jpg','A tournament at a nearby stadium is being held, with a red Chaos Emerald as the prize. Sonic, Tails, Knuckles, Rouge, Amy, Emerl, and several of their Station Square friends show up to participate in this outstanding event...','[]','2005-02-19','163430');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#46','sonic-x',46,'A Wild Win','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163438/original.jpg','The fight tournament draws to a close with Emerl being the winner. However, Emerl starts going beserk after holding the Chaos Emerald and begins to destroy everything in his path. When Amy, Sonic, Knuckles, Tails, and Rouge are unable to stop it, Cream shows up to confront her robotic friend. Will she be able to talk Emerl into ceasing his uncontrollable mayhem, or will she have no choice but to fight and shut him down?','[]','2005-02-26','163438');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#47','sonic-x',47,'Map of Mayhem','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163449/original.jpg','Eggman, Decoe, and Bocoe hatch a plan to destroy the Equator with a giant Robot, and it''s up to Sonic, Tails, Knuckles, Amy, Chris, and Rouge to stop him.','[]','2005-03-05','163449');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#48','sonic-x',48,'The Volcanic Venture','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163455/original.jpg','With Eggman under the Volcano Sonic, Rouge, Knuckles, Tails and Chris follow him. But is there something hidden from the world there?','[]','2005-03-12','163455');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#49','sonic-x',49,'The Beginning of the End','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163463/original.jpg','It is discovered that Earth and Mobius are merging. If they join together completely, then time will stop forever. It is decided that Sonic and co. must return home through chaos control. This upsets Chris, who runs off to confront Eggman thinking it is one of his tricks to get rid of Sonic.','[]','2005-03-12','163463');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#50','sonic-x',50,'Running Out of Time','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163474/original.jpg','This episode tells of what happens before Sonic &amp; co. leave for home. Everyone is sad that they''ll leave, especially Chris. There are many flashbacks to the first two episodes until they leave. Eggman, Cream, Amy, and Knuckles leave, but at the last second, Chris shuts the portal to Sonic''s world, leaving Sonic trapped on Earth. So begins the (not so) long journey of Chris and Sonic...','[]','2005-03-19','163474');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#51','sonic-x',51,'Friends ''Til the End','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163495/original.jpg','After Chris stops him from going home, Sonic goes on a long journey with Chris, who decides to run away. However, his parents want him back and they soon go looking for him. Will Nelson and Linsey find Chris or has he run away forever?','[]','2005-03-19','163495');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#52','sonic-x',52,'A New Start','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163507/original.jpg','All the animals (except Sonic) are now back at their original world. Amy is having dinner with Cream and Cream''s mom at their house, and Knuckles and Rouge are talking in the woods. Suddenly, Eggman hatches a plan, and Tails gets in his plane to stop him. Tails, is almost beaten, but luckily an old friend, Sonic, as Super Sonic, has finally returned, and pops in, saves him and beats Eggman. Meanwhile in Chris'' world years have passed. Chris is now a adult. Suddenly he starts remembering all the fun, and the struggles he had with Sonic as a kid.','[]','2005-03-26','163507');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#53','sonic-x',53,'The Cosmic Call','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163512/original.jpg','In the episode''s opening, Super Sonic is fighting against a mysterious robot. Super Sonic is unable to defeat him and he sends the Chaos Emeralds away to avoid his opponent to take them from him. Without the Emeralds, Sonic loses his energy and he falls to his planet. Another robot (a Metarex) follows him. Back on the planet, Tails, Amy, Cream &amp; Cheese watch the sky and assist to a meteoric shower. However, a space ship crashes near them, carrying a strange alien girl named Cosmo. After introducing themselves, they are surprised by the arriving Metarex who starts destroying the forest with laser beams. Tails, accompanied by Cosmo, starts fighting it with the X-Tornado and he''s soon joined by Knuckles. Sonic (who was rescued by Dr. Eggman) arrives but they can''t beat the Metarex. The last Metarex was able to finish his duty: which was to remove the "planet egg". Cosmo explains that the planet egg "is the lifeforce that sustains their world". Sonic, Tails, and Knuckles make a last effort to save the Planet Egg, but the Meterex escapes. Cosmo then tells Sonic that he is the final hope to save the galaxy. At the same moment, Chris (who is now 18) completes his new machine that will transport him to Sonic''s world. It works, but Chris arrives in his 12-year-old body.','[]','2005-09-10','163512');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#54','sonic-x',54,'Cosmic Crisis','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163537/original.jpg','Chris arrives in Sonic''s world as his 12-year-old self. He makes contact with everyone, but Sonic faints shortly after. Apparently, the recent battle tailed him off. Back to Cream''s house, Cosmo explains the Metarex goals and the consequences of the planet egg''s removal. Cosmo also admits that she''s the only survivor from her group, which was eliminated by the Metarex. Everybody (except for Knuckles, who''s suspicious of her) agrees that the Metarex must be stopped and they decide to go into space to destroy the Metarex and to find the lost Chaos Emeralds. Luckily for them, Tails has just finished to build his new invention: a big flying fortress called the Blue Typhoon. Unfortunately, his new ship used to be powered by the Chaos Emeralds. Chris thinks that they could use the Master Emerald. Knuckles disagrees, but with some female persuasion, he finally agrees. At the same time, another Metarex is sent to the planet in order to destroy Sonic and the Blue Typhoon. A fight engages between the Metarex and Sonic &amp; Knuckles. With the help of the Typhoon''s primary weapon, the "Sonic Power Cannon" ("Sonic Driver" in the original Japanese version), the Metarex is destroyed. The Blue Typhoon takes off, but it is followed by Dr. Eggman and Rouge.','[]','2005-09-17','163537');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#55','sonic-x',55,'H2Whoa','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163557/original.jpg','The Blue Typhoon is now on its way to a new adventure. Knuckles thinks that a Chaos emerald is nearby due to the Master Emerald''s reactions. A planet is located and according to Sonic''s guidebook, this is a dry planet. However, they find out that it''s covered by water. Accidentally separated of the others, Chris &amp; Sonic arrive to a Metarex base, where several Metarex await them. The fight is engaged, but Chris, wanting to help his friend, is unable to punch a Metarex without hurting himself. Eventually, Sonic is captured and Chris is able to escape. Informing Tails of the situation, Chris wants to rescue Sonic with the X-Tornado, but Tails insists that Chris won''t be capable of his own. This leads Chris to question himself about his utility in their mission. Finally, Amy and Tails succeed to rescue Sonic with the X-Tornado, but Metarex attack the plane and by accident, Sonic falls straight toward the water. Chris arrives with another plane and saves Sonic with his own invention: hover shoes. The Metarex are finally defeated, the water retires from the planet and the Dark Blue Chaos Emerald is found.','[]','2005-09-24','163557');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#56','sonic-x',56,'An Enemy In Need','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163594/original.jpg','After saving the planet in the former episode, Sonic and his friends are thanked in a feast. Dr. Eggman is watching the scene and he thinks about his next scheme to take away the Chaos emerald. Bokkun suggests a plan to Eggman, but the evil doctor doesn''t notice that it has been elaborated by Rouge, who made her way to the Egg Carrier. Eggman soon finds Knuckles and he tries to persuade him that he tired to be a bad person and he wishes to leave the planet by using a Chaos Emerald. Knuckles believes him and he finds the others in order to take the Emerald they just found and to give it to Eggman. Sonic disagrees and both of them engage in a fight. Taking advantage of the situation, Eggman almost takes the Emerald, but he is stopped by Amy and the others. Then, a giant robot controlled by Bocoe and Decoe appears suddendly and it captures Cosmo. Eggman summons Sonic to give him the Emerald and he would let Cosmo go away. But at the same moment, a frog-shaped Metarex rises from the ground and it grabs the Emerald. Eggman let Cosmo go and he engages a fight against the Metarex. However, Eggman is defeated. It''s Sonic''s turn to fight the Metarex and, with the help of the Sonic Power Cannon and a Chris'' trick, the blue hedgehog is victorious. The episode ends as Knuckles apologizes for being fooled by Eggman.','[]','2005-10-01','163594');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#57','sonic-x',57,'A Chilling Discovery','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163609/original.jpg','With the help of Chris'' new program, the Blue Typhoon spots a Chaos Emerald on planet Freezy. Followed by Dr. Eggman''s Crimson Egg, the Blue Typhoon approaches planet Freezy, but it''s attacked by a Metarex and it crashes on the planet. Sonic, Chris, Knuckles and Cosmo decide to go get the Chaos Emerald with the X-Tornado. Rouge is also on her way for getting the emerald before Sonic. Everybody has to fight Metarex before reaching an ice palace, where the emerald is supposed to be located. Sonic''s group find it, but it''s sealed in a solid ice block. A more powerful Metarex appears and gets power from the emerald to become even stronger. A fight engages and Cosmo finds the way to defeat it with a laser beam. Knuckles finds the Chaos Emerald but before he gets it, Rouge steals it. However, Tails discovers that the emerald was a fake one.','[]','2005-10-08','163609');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#58','sonic-x',58,'Desperately Seeking Sonic','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163630/original.jpg','The Blue Typhoon detects two Metarex who just stole a Planet Egg on a jungle planet. Sonic destroys the biggest Metarex with the Power Cannon, but he is launched too hardly and he falls straight to the planet. He crashes on Dr. Eggman, who is already on the planet, and he takes the Green Chaos Emerald that the evil doctor has just discovered. Having landed on the planet, Tails and Knuckles get aboard the X-Tornado in order to find Sonic, leaving Amy behind. Amy desperately wants to find Sonic by herself and she enters into the jungle. She is accompanied by Cosmo, who wants to find the Planet Egg, and Cream &amp; Cheese, who don''t want to be left alone. Discovering he was left alone, Chris contacts Tails, but at the same moment, the X-Tornado spots a Chaos Emerald. Inside the jungle, Amy, Cosmo, Cream &amp; Cheese struggle to find Sonic and the Planet Egg, but they are captured twice by the small Metarex who survived the previous fight. However, they escape and are able to take possession of the Planet Egg. Sonic is still running in the jungle with the Chaos Emerald in his hand and he is found by Tails and Knuckles. Dr. Eggman arrives and he steals the emerald from Sonic. Sonic and Knuckles prepare to fight, but the girl group and the Metarex appear. Eggman captures everybody (even the Metarex). The Planet Egg begins reacting and huge creepers wraps everyone. Chris arrives and Sonic is able to free himself and with a little help from Tails and Chris, he defeats Eggman. Finally, the Planet Egg gets back where it belongs and Sonic &amp; his friends get back to the Blue Typhoon with two Chaos Emeralds in account now.','[]','2005-10-15','163630');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#59','sonic-x',59,'Galactic Gumshoes','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163649/original.jpg','Chris'' grandfather, Chuck, finds a way to teleport material objects to Sonic''s world. The stuff is discovered by Vanilla and she asks the Chaotix Detective Agency to deliver it to Chris. She''s also worried about her daughter Cream and she asks them to check on her. Vector accepts, but Espio tells him that they don''t have any space ship. However, Chuck also sends a space ship to Sonic''s planet and the Chaotix are on their way. Aboard the Blue Typhoon, Sonic and Knuckles are playing chess. Knuckles takes time before moving a piece, and Sonic decides to take a quick walk on the ship. Accidentally, Sonic slips from the ship and he diverts into space. Knuckles leaves the Typhoon to retrieve him. Inside the ship, Tails points out that another space ship is approaching and everybody is convicted that it''s a Metarex ship. Vector, Espio and Charmy try, one by one, to get aboard the Blue Typhoon, but they are all thrown out from it. They take a little distance from the Typhoon temporarily, but Tails pursues them. He discovers a little house on the Chaotix ship and he realizes that it wasn''t an enemy ship. Chris and the other ones apology and everybody unburdens the Chaotix ship from the stuff sent by Chris'' family. Vector, having misinterpreted Vanilla''s wishes, decide to leave the Blue Typhoon, taking Cream with them. Vector kidnaps Cream, but Cosmo sneaks along with them. Luckily, Sonic is back and he fights Vector in order to take the girls back with him. Finally, an agreement is settled and Cream gets back to the Blue Typhoon. The episode closes in Eggman''s Egg Carrier, where Rouge finds a strange capsule in a secret room.','[]','2005-10-22','163649');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#60','sonic-x',60,'Trick Sand','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163674/original.jpg','The episode opens with a dream from Chris, where he remembers the events of Space Colony ARK and the loss of Shadow. He is awakened by Tails who tells him he has just found the signal from a Chaos Emerald. Inside the Crimson Egg, Rouge returns to the secret room she has just discovered and she spots the Red Chaos Emerald which is powering the strange capsule. She tries taking the emerald, but she launches an alarm and at the same time, she discovers that Shadow is currently hibernating inside the capsule. She''s found out by Dr. Eggman. The Blue Typhoon follows the Chaos Emerald''s signal to a dark, abandoned planet. Sonic, Amy and Knuckles search inside an old castle, while Chris and Cosmo look inside an ancient colony. Sonic''s group quickly notices that the castle is a trap. In fact, it''s an illusion created by a Metarex. This Metarex suddendly turns the castle into a sandtrap and almost catches Sonic. The Metarex attacks Sonic''s group and Chris, who is in the Hyper Tornado. Sonic tries to counter-attack, but he is not able to beat the Metarex. Chris tries his luck and he fails too. At the same moment, in the Egg Carrier, Shadow awakens and he teleports himself to the fight place. He easily defeats the Metarex and he shows his presence to everybody. He looks at Chris, who just said Shadow''s name, and he disappears with the Purple Chaos Emerald.','[]','2005-10-29','163674');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#61','sonic-x',61,'Ship of Doom','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163686/original.jpg','The show opens with a fight involving a huge Metarex named Scarship and an armada of smaller ships. Scarship destroys every ship and he''s assigned to a new mission: to destroy Sonic and Dr. Eggman. Inside the Blue Typhoon, everybody questions himself about Shadow''s return. Aboard the Egg Carrier, Dr. Eggman finds out that Scarship is approaching and the battle engages. Eggman sends Shadow to destroy Scarship, but Shadow is unable to do the job. Rouge flees from the Egg Carrier, just before Starship sends a missile and seems to have destroyed it. Rouge informs the Blue Typhoon''s crew of the situation and sends them images from the battle. Cosmo recognizes Scarship, it''s the Metarex who destroyed her group''s ship. Cosmo begs Tails to flee away, because she doesn''t want to risk her friend''s lives. However, Sonic and the others insist that they need to face Scarship. The battle starts and nobody gets the advantage. However, Sonic, Amy and Knuckles leave the ship unnoticed and they find a way to block Scarship''s weapons. Scarship decide to destroy the Blue Typhoon by crashing into it. The Typhoon won''t be able to get out of its way in time, but Shadow appears from nowhere and takes Scarship away. It appears that Eggman was able to escape from Scarship. Sonic and Shadow get inside Scarship and they destroy the engine room. However, Scarship won''t ever surrender and it''s about to self-destroy. Shadow is able to freeze time around it and Sonic defeats it with the Power Cannon.','[]','2005-11-05','163686');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#62','sonic-x',62,'An Underground Odyssey','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163739/original.jpg','The show opens with a sequence inside Cosmo''s ship and ends when Scarship (see previous episode) destroys it, leaving Cosmo alone. Then, we find out the Blue Typhoon''s crew on a new planet. It seems that there''s a Chaos Emerald nearby. Tails, Knuckles and Cosmo follow the emerald''s track to an abandoned city. Knuckles discovers a deep gorge. Lower, there''s a cave. Tails and Cosmo enter, but Cosmo accidentally pushes a button which launches an avalanche and seals them inside the cave. Tails still receives the emerald''s signal and he and Cosmo pursue their searches. Inside the Blue Typhoon, Amy receives a distress call from Knuckles and she informs Chris, Sonic, Cream and Cheese (who are all aboard the X-Tornado) of the situation. Inside the cave, Tails and Cosmo discover a big factory full of Metarex. They enter unnoticed and they find the Chaos Emerald inside a manufacturing plant of fake emeralds. They are found out by the Metarex, but they are able to escape with the White Chaos Emerald. Then, Tails fools the Metarex with special "fireflies". Tails and Cosmo are found retrieved by the Metarex and they steal the emerald from them. Tails engages a fight and Cosmo can take back the emerald. Tails is caught by a Metarex, but fortunelately for them, Sonic and the others come to the rescue. Tails and Cosmo also are starting to have feelings for each other.','[]','2005-11-12','163739');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#63','sonic-x',63,'Station Break-In','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163785/original.jpg','Dr. Eggman discovers that the last two Chaos Emeralds (Cyan and Yellow) are located inside a huge Metarex fortress. The Crimson Egg and the Blue Typhoon arrive on location at the same moment. Eggman suggests Sonic to put their efforts together in order to enter inside the fortress. His plan: a little group will enter first and disconnect the fortress'' security system, so the other ones could penetrate. Eggman sends Shadow and Rouge while Chris volunteers to accompany them. They enter with the help of Chaos Control. Rouge tries to get away from Shadow and Chris to get the Chaos Emeralds for herself. She reminds Shadow of the ARK and Maria, which causes Shadow to drop his guard as he has a sort of ''meltdown''. Rouge tries to escape, but is ambused by a Metarex. Shadow saves her and tells her not to run off. Chris finds the control room and they succeed in their job. Sonic &amp; Knuckles penetrate in the fortress aboard the X-Tornado, Amy &amp; Cosmo follow them and Eggman, Bocoe &amp; Decoe are right behind. However, Eggman secretly installed a special device on each ship and he can take control of Sonic and Amy''s ships. Eggman almost succeeds, but Sonic finds the emeralds first. The only thing: he is welcomed by an entire army of Metarex, led by Dark Oak, the Metarex leader, and the battle is about to begin.','[]','2005-11-19','163785');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#64','sonic-x',64,'A Metarex Melee','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163811/original.jpg','The fight between Sonic and Dark Oak starts. Sonic directly attacks Dark Oak, but he instantly disappears: it was a hologram. Outside the fortress, a Metarex armada, led by Red Pine, is approaching. Surprisingly, the Red Pine army begins to attack their own fortress, while there still are Metarex inside. Shadow, Rouge and Chris are transported, via Chaos Control, inside the Egg Carrier. Chris finds a way to steal the emeralds found by Eggman and flees away by using one of Eggman''s mini-ships. Shadow follows him and he stops him. The seven Chaos Emeralds are put together, transforming Sonic and Shadow into their super forms. Super Sonic and Super Shadow engage into a fight inside the fortress. At the same moment, a gravitational field is activated inside the fortress and it starts to destroy itself from the inside. The Metarex armada is destroyed, Super Shadow sees the Crimson Egg fly down to the center of the gravity feild and jumps in to follow it and stay with it, while the Blue Typhoon escapes with the power of the Master Emerald. However, during the event, the seven Chaos Emeralds disappeared.','[]','2005-11-26','163811');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#65','sonic-x',65,'Mission: Match-Up','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163822/original.jpg','The Blue Typhoon encounters the Chaotix ship. Once aboard the Typhoon, Vector and Espio explain that they lost themselves in space and that their radio got broken. Tails agrees to fix their ship and he warns them that he doesn''t want any trouble on the Typhoon. Tails begins his work when Cosmo brings him lunch. She reveals that she''s planning a surprise for everybody. The Chaotix watch the scene and Vector notices the growing relationship between Tails and Cosmo. In order to thank Tails for fixing his ship, Vector decides to help him winning Cosmo''s heart. At the same time, Tails unintentionally discovers Cosmo''s surprise : she plans to throw a party on the ship. Cosmo is disappointed because it won''t be a surprise for Tails now, but the little fox tells her that she won''t be able to prepare everything all by herself. Also on the scene, the Chaotix propose their help and Vector takes it as an opportunity to throw his match-up plans. However, they all fail one by one. Espio believes that their relationship should develop naturally. After finishing the preparations, the Chaotix go get everybody to the party room when they cross Knuckles'' path. Knuckles was used against his will in one of Vector''s plans and he decides to take his revenge. Accidentally, they end up in the party room and they ruin everything. Arriving on the scene, Tails and Cosmo are disappointed, but Sonic says it''s no problem and that they''ll put everything back. He also thanks Cosmo for her party idea. The episode ends with Cosmo and Tails watching the stars outside in space.','[]','2005-12-03','163822');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#66','sonic-x',66,'Clash in the Cloister','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163844/original.jpg','The Blue Typhoon is pulled into the Intergalactic Cloister, a strange region of space. Eager to do battle, Metarex Commander Yellow Zelkova launches an attack on the Blue Typhoon. Sonic and Knuckles team up to fight him, finding that Zelkova is too powerful for them. However, they then trick him into freeing the Blue Typhoon from a formation of space stalactites, and put him in line with the Sonic Driver cannon. They fire, and Zelkova is thrown back, but not destroyed. They then escape as he swears vengeance.','[]','2006-02-04','163844');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#67','sonic-x',67,'Teasing Time','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163873/original.jpg','Sonic and friends come across a barren planet with 500 Chaos Emerald signals coming from it. Black Narcissus is inside, and sends a message to the Typhoon, a message that only Cosmo can understand. He then sets off fireworks, allowing Cosmo to escape to the planet undetected. Unexpectedly, Chris follows, but Narcissus captures both him and Cosmo. When Chris tries to escape with Cosmo, Chris is attacked and stabbed (knocked out in the English version). Sonic comes to rescue them and is horrified by their predicament, but because the Chaos Emeralds they detected were fake, Sonic draws upon their negative energies and becomes Dark Super Sonic. Dark Super Sonic then proceeds to destroy two Metarex robots Narcissus had prepared just for him for an "experiment" (Gold for strength and Silver for speed). Suddenly, Eggman appears and has Decoe and Bocoe hold Narcissus down while Bokkun kicks him, dealing some damage. Chris and Cosmo are saved by Shadow while Rouge destroys the machine that makes the fake Chaos Emeralds. Sonic and his friends then go back to the Blue Typhoon and Eggman talks to Black Narcissus about what''s happened.','[]','2006-02-11','163873');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#68','sonic-x',68,'A Revolutionary Tale','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163896/original.jpg','While traveling through space, Dr. Eggman and his forces come across a group of humans battling the armada of Pale Bay Leaf. The two groups talk, and Shadow and Rouge get to know a human girl named Molly. After seeing Shadow in battle, Molly comes to believe that Shadow is a hero of folklore named Black Wind. Shadow, Rouge and Molly infiltrate an old factory where they find the White Chaos Emerald. Eggman is then taken prisoner by the humans, revealing that they have made a deal with the Metarex. Molly flees in shame*, while Shadow uses the Chaos Emerald to devastate the Metarex forces. Despite the damage, Pale Bay Leaf survives, and communicates with Dr. Eggman.','[]','2006-02-18','163896');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#69','sonic-x',69,' The Planet of Misfortune','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163914/original.jpg','In this episode, Sonic and the others find a meteor in space while searching for the Chaos Emeralds. Tails pulls it in, and they find it to actually be a space ship. Inside, small chao-like creatures called Marmolians are discovered and it is revealed that they have the Green/Cyan Chaos Emerald. The Marmolians and Sonic go back to their home planet, the Planet Marmolim, and Sonic destroys a diseased part of the planet that encased the Planet Egg. Amy thinks they have magic on the planet, so she tries to put a love spell on Sonic. However, it ends up backfiring, and instead works on Tails and Cosmo at the end of the episode, leading to the two embracing while watching the moon. This episode basically confirms Tails and Cosmo''s relationship, while Amy gets extremely angry that she didn''t catch Sonic.','[]','2006-02-25','163914');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#70','sonic-x',70,'Terror on the Typhoon','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163937/original.jpg','While traveling in the Galactic Cloister, the Blue Typhoon comes under attack from the Metarex fleet, led by the three surviving commanders and Dr. Eggman. Sonic attempts to attack from the Sonic Driver, but Dr. Eggman deploys a shield that not only repulses Sonic''s attack, but causes an overload explosion that puts Knuckles out of commission. With Sonic and Knuckles both out cold, Tails assumes command reluctantly until Cosmo boosts his confidence. Coming up with a plan, Tails pilots the Blue Typhoon towards a black hole in the Cloister. Sonic and Knuckles recover long enough to deploy the Sonic Driver, reversing the black hole and allowing the Blue Typhoon to escape. Visiting the medical bay, Tails is praised by the injured Sonic and Knuckles.','[]','2006-03-04','163937');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#71','sonic-x',71,' Hedgehog Hunt','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163951/original.jpg','Following their battle with the Metarex fleet, Sonic and the gang are stranded on an alien planet with the Chaotix, who are running a cafe to pay for parts to their own ship. Dr. Eggman arrives looking for Sonic and the others, while Pale Bay Leaf waits in orbit to shoot the Typhoon down. Helping out Sonic and the gang, the Chaotix provide parts for their ship. However, Dr. Eggman provides the real assistance when he disguises the Crimson Egg as the Blue Typhoon and takes the full force of the Metarex attack. Pale Bay Leaf moves off, and no ambush awaits the real Typhoon once it takes off.','[]','2006-03-11','163951');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#72','sonic-x',72,'Zelkova Strikes Back','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163968/original.jpg','Yellow Zelkova attacks the Blue Typhoon, equipped with a special energy shield built by Dr. Eggman. Sonic attempts to stop him, but is unable to break through the shield. Picking up where they left off, Zelkova and Knuckles get into a fierce battle, during which Knuckles smashes Zelkova''s knee and breaks the spurs on one of his gloves. Using cable from the Blue Typhoon, Sonic and the others channel lightning to overload Zelkova''s shield. Zelkova''s mechanical outer body is destroyed, revealing his flesh form beneath. Zelkova attacks, but is knocked into a nearby lava pit by Knuckles. Pale Bay Leaf informs Eggman of Zelkova''s demise, mocking the failure of his shield. Shadow and Rouge find a fake Chaos Emerald at the top of the tree, but they hear groaning from its base. They find Leon (from the Resistance in Episode 68) being consumed by the tree, saying that the Metarex betrayed them. He also give Shadow a memory chip and says it''s not too late to destroy the Metarex.','[]','2006-03-18','163968');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#73','sonic-x',73,'The Cosmo Conspiracy','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163982/original.jpg','Shadow attacks the Blue Typhoon trying to kill Cosmo for reasons (at the time) unknown. Despite the efforts of Sonic, Tails and Knuckles to hold him off, Shadow reaches Cosmo. However, before he can harm her, Dark Oak''s flagship arrives and steals the Chaos Emeralds, and Cosmo is revealed to have an implant that allows the Metarex to monitor everything she hears and sees. Along the way he nearly kills Sonic, Tails, Knuckles, and Chris','[]','2006-04-01','163982');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#74','sonic-x',74,'Eye Spy','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/163999/original.jpg','When the team discovers that Cosmo''s brain is emitting a signal to the Metarex, they plan on trying to eliminate the signal, except that the signal is connected to the part of her brain that translates sounds and sight. While Tails and Cosmo are torn about this, Knuckles pushes for the surgery. Meanwhile, Amy starts searching for Sonic (as always), but ends up bumping into Rouge. They both discover that this planet is not only Cosmo''s homeworld, but the Metarex''s as well. They also discover that Cosmo''s people were able to transform into huge dinosaur-like beings to protect their planet from an alien invasion. However, a few of them wanted to be able to completely destroy the alien hoarde, and so crystallized the Planet Egg in order to keep the transformation from sapping their energy. They eventually led to the abandonment of the planet. Cosmo, horrified by the fact that the Metarex are using her to spy on them, intends to leave, but Tails reassures her that they all will help her defeat the Metarex. Sonic and the rest of the gang also support the new resolution, and they all are ready for an attack on the Metarex, maybe the last attack. At the end of the episode, Bokkun arrives, telling Shadow and Chris that Eggman has been captured by the Metarex.','[]','2006-04-08','163999');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#75','sonic-x',75,'Angel of Mischief','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/164012/original.jpg','When Bokkun shows everyone Eggman''s message (telling that the Metarex are starting to gather at galactic coordinates (0-0-0) because of a thousand-year prophecy), the gang starts lifting off to go beat the Metarex once and for all. Unfortunately, they leave Shadow behind! However, the Chaotix find Shadow and offer him a ride (for free, which is the surprising part) to galactic coordinates (0-0-0). Once Sonic and the gang reach (0-0-0), they find the Metarex fleet there, ready while a Planet Egg warps in from another universe. The Egg is in the center of a planet of water, which, combined with the light of the Chaos Emeralds, help Dark Oak and two other Metarex to mutate into a giant plant-dragon mix! Sonic''s fleet starts attacking the planet, but then Sonic is catapulted into the air by a pillar of water! Dark Oak then swallows Sonic, who plunges face-first into the planet. "Ha! Now Sonic the Hedgehog, how can you hope to defeat us? Water is your weakness, and our strength! Now Forestation will be unstoppable!" Meanwhile, Chris infiltrates Dark Oak''s ship to blow Eggman, Bocoe, and Decoe out. At the same time, Shadow and the Chaotix fight more Metarex, Shadow asking every Metarex he comes across where Dark Oak is. Eventually, the ship comes apart to reveal a giant tree, which attaches to the aquatic planet and starts growing to an unimaginable size!','[]','2006-04-15','164012');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#76','sonic-x',76,'The Light in the Darkness','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/164023/original.jpg','Amy tries to rescue Sonic from the watery planet, but everyone else keeps her back, trying to come up with another plan. Then, Rouge comes up with a brilliant idea: use the Master Emerald to cut off the energy supply to Dark Oak! The team charges up the Sonic Driver with the Master Emerald and fires it at Black Narcissus and Pale Bayleaf, destroying them. Unfortunately, after this is done, the Master Emerald shatters, and it is revealed that the Metarex have sucked up all the Chaos Emerald''s energy! Dark Oak''s beast head becomes extremely weak because of a hit from the Sonic Driver, and finally ceases movement. The planet expands, taking Dark Oak along with it. Inside the planet, Sonic sees what happens after the Forestation process is complete. He manages to fight a bunch of sand monsters and plant-like tentacles, only to find out he''s fighting in a dream. Suddenly, Amy spots Sonic inside the planet is able to get Sonic out of there, crashing through the roots into the water to rescue him but is knocked unconcsious. However as Amy and Sonic are going down an energy sphere surrounds them, protects them and heals them. They fly out of the planet and Amy hugs Sonic in relief and happiness. Suddenly, the planet condenses into a giant seed-like object. Sonic stares at it, probably in despair.','[]','2006-04-22','164023');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#77','sonic-x',77,'A Fearless Friend','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/164034/original.jpg','When the giant seed finally reaches the final stage of its metamorphosis and starts sucking the life out of everyone except for Cosmo, she takes the Chaos Emeralds to Eggman, thinking that he''ll know what to do. Unfortunately, Dark Oak attacks Cosmo, who drops the Chaos Emeralds into space. Thankfully, they close in on Sonic and Shadow, who use them to transform into Super Sonic and Super Shadow and attack the Metarex seed. But, once they destroy it, they reveal an even smaller planet with a gravitational force that could potentially destroy the whole galaxy! Cosmo feels helpless but her mother, in her mind, assures her that she is the one who will save the galaxy. She then transforms into a new form and becomes determined to stop this once and for all. She flies over to the planet, passes through the gravitational force that neither Super Sonic nor Super Shadow could pass through, and plants herself on top of it. She then becomes a tree, saying that she has now immobilized Dark Oak. She tells Tails to load and fire the Sonic Driver and shoot it at the planet. Everyone is shocked and does not know whether or not to risk saving the galaxy if they''re going to kill Cosmo in the process. Tails, however, is very hesitant, but Cosmo re-assures him that her seeds will be spread throughout the galaxy. He then thinks back to all of the good times they''ve had and their love and, tearfully, fires Super Sonic and Super Shadow at the planet, completely destroying it. Tails and Cosmo, during the ending sequence (which was cut from the English dub), say farwell to each other. At the very end as Cosmo floats off, she says "I love you."','[]','2006-04-29','164034');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sonic-x#78','sonic-x',78,'So Long Sonic','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/164046/original.jpg','The episode starts off with Vanilla stopping by the Chaotix Detective Office to thank the Chaotix for all that they did for her and Cream. Amy and Cream then bring a whole bunch of snacks to Tails to try and cheer him up. (Note: This entire first part, almost four minutes long, was not shown in the English dub of the episode.) Chris then flashes back to the point just when the planet with Cosmo on it was being destroyed. Lucas is seen following Hertia to peace. Suddenly, the planet begins to expend all of its energy. Punching Sonic out of the way (which looked very painful for Sonic), Shadow uses the last of his energy to perform Chaos Control to stop time, giving everyone else a chance to escape. Eggman then worries that Shadow may not have survived the Chaos Control he did to save everyone, and he begins to feel some remorse for Shadow. Meanwhile, Sonic approaches Tails with only a seed from Cosmo. Tails, already upset about losing her, finally falls into Sonic''s arms, crying as they fly away. Back on their homeworld, Chris and Knuckles have a little discussion about what''s next for Chris, and they fall along the lines of where Chris''s home would be now that he can''t go back. Rouge is seen in Eggman''s ship staring at Shadow''s pod. After a run-in with Eggman, Rouge suspects that he knows something about Shadow''s whereabouts. Eggman commented on Rouges breasts and was smacked, however this was cut out in the English dub. Near the end of the episode, Eggman shows Chris an egg-shaped pod that will take him home, but there''s a catch: Chris only has three minutes to return home, or else he could be stuck in Sonic''s world! Chris has no time to say goodbye to his friends, just as Eggman planned. Chris then leaves Sonic''s universe via Eggman''s pod. Once Chris is gone from sight, Eggman says that with Chris out of the way, he can continue in his creation of the Eggman Empire. Sonic''s last words were "I won''t forgive you, Eggman!" ("Life never stays slow around here for long, thank goodness! Watch out Eggman, I''m coming at''cha full speed!" in the English dub). We then see a pot with a seed (apparently the one Sonic found) in it. The episode ends as the Egg pod with Chris in it flies out into space and then twinkles out. Chris was supposedly sent home.','[]','2006-05-06','164046');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-hill-dyed-rose-madder#1','the-hill-dyed-rose-madder',1,'A Madder Red First Kiss','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/162849/original.jpg','Whilst walking in the evening, Yuuhi is saved from two guys trying to pick her up by Jun''ichi, going away only knowing him as "the Geno Killer". The next day at school, when Yuuhi transfers into Jun''ichi''s class, both are surprised to see each other again so soon. During a discussion with Ayanokouji, she asks Jun''ichi out, shocking the class. It then turns out only to be for a cup of tea, which is how she wanted to express her gratitiude. She learns that he was a former delinquent. The following day, Yuuhi is pressed for details with regards to her first encounter with Jun''ichi, and in his confusion on clarifying matters for the class, Jun''ichi kisses her, only to get beaten up for taking her first kiss. That evening, Yuuhi turns up at the Nagase residence, stating that she is moving in as Junichi''s fiancee, much to his and Minato''s surprise.','[]','2008-10-02','162849');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-hill-dyed-rose-madder#2','the-hill-dyed-rose-madder',2,'A Madder Red Approach','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/162864/original.jpg','A scene from Yuuhi''s past provides some background on the arranged marriage between Jun''ichi and Yuuhi and to her moving in with him. Yuuhi and Jun''ichi have trouble adjusting to living together, and Yuuhi spends her first night sleeping on the couch. The next day afer school Yuuhi goes grocery shopping with Minato for dinner. Yuuhi is amazed by the supermarket and by Minato''s shopping savviness. That evening after supper the Nagase residence loses power and Yuuhi trips in the dark and falls on Jun''ichi leading to another very awkward situation. Minato resets the breakers and power is restored, but Yuuhi blames Jun''ichi and puts him into a headlock, which leads to another awkward situation. Yuuhi ends up sleeping in Minato''s room and the two girls are able to talk and become better friends.','[]','2008-10-09','162864');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-hill-dyed-rose-madder#3','the-hill-dyed-rose-madder',3,'A Mysterious Scream','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/162876/original.jpg','Jun''ichi''s teacher Seijirou Sugishita goes missing in an abandoned portion of the school. The student council president Mitsuki Siina enlists Jun''ichi and his friends to search for him in the abandoned school building. While searching Jun''ichi and Yuuhi fall down a trap door into a pit. The two are forced to work together to try and get out, but are unable to escape. In the same pit Mr. Sugishita wakes up from under a blanket and the trio are found shortly afterward by Minato.','[]','2008-10-16','162876');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-hill-dyed-rose-madder#4','the-hill-dyed-rose-madder',4,'An Indigo Mad Party','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/162890/original.jpg','Karen Ayanokouji, Jun''ichi''s classmate, invites him and his class to her casual "home" party. He is at first not interested, but is dragged along by Minato who also receives an invitation. When they arrive Jun''ichi, Yuuhi, and company find that the party is actually a formal event on a huge cruise ship. Seeing how underdressed everyone is Karen loans them some formal wear, and Minato makes quite the impression on Jun''ichi when he sees her with her revealing dress. This causes Jun''ichi to have awkward feelings about his sister and asks her to cover up. Later, on their way back from the ladies room, the girls discover the kitchen is seriously behind schedule as most of the cooks are seasick. This prompts Minato and the girls to swing into action to save the party. The girls finish the feast and Minato puts on a show slicing up a tuna. Karen, feeling upstaged by the tuna show, puts on her own performance fighting against a giant octopus. This sends a scared Yuuhi running out onto the deck where she trips and activates the fireworks, which ricochet throughout the ship causing a fire in the party hall. Everyone escapes safely except for Minato and Yuuhi, and so Jun''ichi goes into the fire to save them.','[]','2008-10-23','162890');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-hill-dyed-rose-madder#5','the-hill-dyed-rose-madder',5,'A Madder Red First Date','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/162904/original.jpg','Jun''ichi asks Minato to see a monster movie with him, which causes Yuuhi to become angry that Jun''ichi never thought to include her. Just before the trio are about to leave, Minato fakes a phone call and makes up a lie about a previous commitment she forgot about and cannot cancel, forcing Jun''ichi and Yuuhi to go on a date. While the two are out Minato decides to go shopping. After the movie, Yuuhi accidentally walks into a man, spilling her food onto him. Jun''ichi quickly comes to Yuuhi''s rescue again and saves her from the man and his friend. Jun''ichi and Yuuhi continue with their date, but are caught by Mitsuki in the park, and are forced to make a quick exit to avoid Mitsuki''s questioning. On their way home, Yuuhi''s hat is blown onto a rock by the side of the river. Jun''ichi goes to retrieve her hat but accidentally falls in, sending Yuuhi into a panic. Yuuhi rushes them home in a cab and frantically searches the house for medicine and blankets. Minato comes home soon afterwards and cures Jun''ichi with some instant ramen. The next day, everyone at school is talking about Jun''ichi and Yuuhi''s date thanks to Mitsuki and Nagomi (who was also at the movie).','[]','2008-10-30','162904');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-hill-dyed-rose-madder#6','the-hill-dyed-rose-madder',6,'A Golden Yellow Montage','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/162923/original.jpg','Karen invites Jun''ichi and his school friends (including their teacher) up to a mountain hotel resort to make up for the events of the cruise ship party. While there everyone continues to hang around and tease Jun''ichi who is not impressed by their company. Karen takes this to mean that Jun''ichi is not satisfied with the luxuries of the hotel and so she takes the group on a long hike up to the Ayanokouji family''s secret hot spring. There they learn that the secret hot spring is a co-ed bath, which causes some problems since the there are guys and girls. This is shortly interrupted by the sounds of a beast, and Minato takes off to find out the source of the noise. Jun''ichi, worried for his sister, follows soon afterwards with the rest of the group in tow, only to find Minato bathing in the hot spring with a bear and cub. The bear and cub leave and the group go in for a dip, boys on one side, girls on the other, and Jun''ichi tries to deal with his urge not to peek on the girls. Jun''ichi ultimately gives in, but finds that the girls have already left to interrogate Yuuhi about her relationship with Jun''ichi.','[]','2008-11-06','162923');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-hill-dyed-rose-madder#7','the-hill-dyed-rose-madder',7,'A Steel Festival','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/162935/original.jpg','It''s the school Cultural Festival and Yuuhi, Karen, Fuyuhiko and Tsukasa (along with the rest of their classmates) are doing a Yakisoba café. However, they face tough competition from the Yakisoba stand put up by Minato and the tennis club. Meanwhile Jun''ichi is kidnapped by Mitsuki, Nagomi and Mr. Sugishita for secret training regarding a dangerous mission. Back at the Yakisoba café the girls end up wearing their school swimsuits to attract business and end up triumphing over the tennis club''s Yakisoba stand. At the end of the festival everyone is called out to the school track field to witness Jun''ichi''s epic battle in his "Big Genokiller" against a robotic octopus.','[]','2008-11-13','162935');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-hill-dyed-rose-madder#8','the-hill-dyed-rose-madder',8,'A Twilight Desire','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/162943/original.jpg','Tsukasa conducts the school''s sports meet since Mitsuki is sick. After school Tsukasa shows Jun''ichi and Yuuhi an embarrassing picture of the two from the cultural festival she intends to enter in a contest for best media, which eventually leads Jun''ichi to bring up embarrassing things from Tsukasa''s past to put an end to her teasing. This causes Tsukasa to recall her childhood dream to become a voice actress. The next day the students are given a career investigation assignment and Tsukasa sets out fulfill her dream by applying and preparing for an audition. Unfortunately on the day of the audition Tsukasa becomes very nervous and she loses her voice during the audition. Later however, after a talk with Jun''ichi, Tsukasa decides to renew her ambition to become a voice actress.','[]','2008-11-20','162943');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-hill-dyed-rose-madder#9','the-hill-dyed-rose-madder',9,'A Madder Red Birthday','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/162953/original.jpg','Tsukasa''s photo of Jun''ichi and Yuuhi from the Cultural Festival comes in first place as Best Amitié. Minato convinces Yuuhi to help with Jun''ich''s surprise birthday party by getting Jun''ichi''s present, but Yuuhi has a difficult time choosing a gift. She ends up sneaking into Jun''ichi''s room for some clues on what to get him and discovers Jun''ichi''s stash of dirty magazines. While looking through the magazines Yuuhi is caught by Minato and confesses her difficulty trying to find Jun''ichi''s gift. Minato offers to let Yuuhi bake the cake instead as her present to Jun''ichi. The next day at his party Jun''ichi receives many strange birthday gifts from friends and family. Afterwards Jun''ichi finds the cake Yuuhi baked and everyone tries a piece. The cake did not turn out very well, but Jun''ichi tells Yuuhi that it is delicious because she baked it for him. Minato begins to feel jealous.','[]','2008-11-27','162953');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-hill-dyed-rose-madder#10','the-hill-dyed-rose-madder',10,'A Madder Red Confusion','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/162961/original.jpg','Yuuhi is beginning to understand her feelings for Jun''ichi. As a result she fakes being sick and Jun''ichi stays home from school to care for her. Yuuhi demands a redo first kiss and the two finally confess their true feelings. At school the girls encourage Yuuhi to take initiative to move her and Jun''ichi''s relationship to the next level, and Karen announces her intentions towards Jun''ichi. The next day Fuyuhiko confronts Jun''ichi about his feelings for his sister and advises Jun''ichi to make a decision. At Nagomi''s suggestion Yuuhi comes to Jun''ichi''s bedroom in middle of the night dressed as a maid and despite some awkwardness the two are able to become closer. The next evening Yuuhi leaves to report back to her family leaving Jun''ichi and Minato alone. Minato uses this chance to express her feelings for her brother and Jun''ichi is still unsure how he feels for his sister.','[]','2008-12-04','162961');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-hill-dyed-rose-madder#11','the-hill-dyed-rose-madder',11,'A Madder Red Puzzlement','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/162970/original.jpg','Yuuhi meets with her father and rejects her engagement to Jun''ichi, saying she''d rather decide for herself without external pressures. Upon her return Yuuhi senses some weirdness she can''t place in the Nagase home, but neither Minato nor Jun''ichi are willing to admit anything. This causes a rift between Yuuhi and Jun''ichi, which everyone at school notices. When confronted about the apparent rift between the two Yuuhi lies to cover up the true nature of the situation. After school Jun''ichi is whisked away to meet his parents, who have suddenly returned to the country, leaving Yuuhi and Minato alone at home for the evening. After dinner Yuuhi reveals to Minato her intention to leave the Nagase house, the nullified engagement and her hurt at being lied to. Minato finally admits her love for Jun''ichi and her heartache regarding the situation and Yuuhi hugs her.','[]','2008-12-11','162970');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-hill-dyed-rose-madder#12','the-hill-dyed-rose-madder',12,'A Madder Red Hill','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/162975/original.jpg','After Jun''ichi came back home after meeting his parents, Yuuhi was so angry over Jun''ichi lying to her that she decided to break up with him and leave the house that night. The next day, Minato left the house as well in order for Jun''ichi to make a decision between her and Yuuhi. When Jun''ichi got back home from school, he started thinking about the moment Minato came back from training and decided to take care of him a few years ago. Mr. Sugishita suddenly appeared to tell Jun''ichi to become a man and be true to himself, after taking him to the beach. Meanwhile, Yuuhi decided to stay at Karen''s place and Minato stayed with Nagomi. When Jun''ichi got back to the house, he felt lonely and thought about his past and the girl he loves most, by the help of an imaginary Geno-killer, his past self before Minato arrived. With the help of his past self he finally became one with his alter-ego, and Jun''ichi confessed his love to Minato.','[]','2008-12-18','162975');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('fragtime#1','fragtime',1,'Episode 1','60:00',3600,'','','[]',NULL,'271848');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('haruka-nogizakas-secret#1','haruka-nogizakas-secret',1,'It''s Over...','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/51458/original.jpg','After Yūto Ayase returns an anime magazine to the school library, he accidentally runs into the most popular girl in school, Haruka Nogizaka, and discovers her secret that she is an anime and manga otaku which greatly distresses her. Haruka starts avoiding Yūto at all costs which causes others around them to blame Yūto for doing something bad to her. Eventually, Yūto finds Haruka on the school roof where he explains that he will not tell anyone about her secret hobbies if she does not want anyone else to know. This makes Haruka very relieved and happy that if anyone had to find it that it was Yūto.','[]','2008-07-03','51458');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('haruka-nogizakas-secret#2','haruka-nogizakas-secret',2,'It’s my first time…','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/51459/original.jpg','Yūto and Haruka start spending more time together, such as walking to school together, which causes their peers to get annoyed that Haruka would be hanging out with someone like Yūto. Haruka asks Yūto to accompany her to Akihabara on Sunday and he agrees. The two spend most of the day going from store to store looking at the goods but not buying anything, though Haruka wastes some money on a toy vending machine. Yūto and Haruka even go to a maid café for lunch where Haruka is dressed in a pink maid uniform and gets her picture taken with Yūto. At the end of the day, they discover the handheld gaming console Haruka had intended to buy was sold out for now. This distresses Haruka, but Yūto cheers her up later by assuring her that he had a good time today with her.','[]','2008-07-17','51459');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('haruka-nogizakas-secret#3','haruka-nogizakas-secret',3,'“This is it…”','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/51460/original.jpg','The day before a test, Yūto comes over to Haruka''s mansion and meets her younger sister Mika and two of her maids, Hazuki and Nanami. The next day at school, a guy bumps into Haruka which causes her bag to go flying which also exposes the Comiket catalog she had. Yūto manages to make everyone believe the catalog is actually his and Haruka only picked it up, though after this Haruka does not come to school for three days. He goes to see her where he finds out from Mika how her secret was exposed during middle school and she had to transfer schools due to being isolated from her peers. Yūto assures her that he will never leave her which relieves her so much that the next day she affirms after a short conflict that the catalog is actually hers.','[]','2008-07-24','51460');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('haruka-nogizakas-secret#4','haruka-nogizakas-secret',4,'Is it okay…?','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/51461/original.jpg','Yūto, Haruka, Mika and Nanami become increasingly worried about Hazuki''s attempt to distance herself from the family and thus decide to follow her on a shopping trip, meeting up with various familiar faces like Yūto''s otaku friend Nobunaga, Yūto''s sister Ruko and their teacher Yukari. Mika and Nanami eventually becomes distracted in buying lingerie, leaving Yūto and Haruka to the job and almost came to a conclusion that Hazuki was about to get married and quit her job. Before going home, they had a misunderstanding with a bridal shop where they are thought to be customers and were given a chance to take a portrait together with Yūto wearing a tuxedo and Haruka in a wedding dress. That night, Hazuki, much to everyone''s relief, explains that she is not quitting, but was just going to a hardware store, which was located above the bridal shop, to fix her chainsaw.','[]','2008-07-31','51461');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('haruka-nogizakas-secret#5','haruka-nogizakas-secret',5,'When you stare at me like that…','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/51462/original.jpg','The girl Yūto already bumped into twice turns out to be Shiina Amamiya, the new transfer student into his class. The school swimming tournament is coming the following week, but while Shiina can do an arrange of other skills, swimming is not one of her strong points, so Yūto and Haruka help her prepare in the school pool, but Yūto''s sister, and Haruka''s sister and maids come along too. At the tournament, Shiina gets a leg cramp during the race and Yūto jumps in to save her, and he takes her to the infirmary. She was not seriously injured, and was more shocked than anything else; Yūto reassures her that she tried her hardest, and that is what matters.','[]','2008-08-07','51462');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('haruka-nogizakas-secret#6','haruka-nogizakas-secret',6,'It’s…Natsu-Comic','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/51463/original.jpg','Yūto and Haruka attend the summer Comiket convention together, but since it is the first time for both of them, they underestimate the massive scale and hoards of people who attend. Mika, Hazuki, and Nanami tag along in disguise and help Haruka obtain a dōjinshi she wanted, and to get her out of trouble when people started taking pictures of her. Yūto and Haruka grow closer throughout the day, but after he leaves her at her house, Yūto is asked if he and Haruka were followed by anyone at the convention, but he says he did not see anyone like that. That night, a frantic Haruka unexpectedly shows up at Yūto''s house.','[]','2008-08-14','51463');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('haruka-nogizakas-secret#7','haruka-nogizakas-secret',7,'…I’m in love!','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/51464/original.jpg','Haruka reveals that her father, Gentō, found out about her hobby and went on a rage, confiscating her anime goods and she leaves with her first issue of Innocent Smile. She hides in Yūto''s house alongside Hazuki, while Mika prepares a ''secret weapon'' to counter their father. Unfortunately, the next morning, Gentō arrives and assaults the Ayase house with his personal squad, the Hell Hounds. Haruka refuses to go home, and Yūto openly protests about the ostracization towards anime-otaku and disapproval towards Haruka''s hobby. Eventually, Mika and Nanami arrives with their ''secret weapon'': Haruka''s mother Akiho, who verbally and mentally brings down Gentō and makes him leave after apologizing for his outburst.','[]','2008-08-21','51464');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('haruka-nogizakas-secret#8','haruka-nogizakas-secret',8,'…Onii-san','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/51465/original.jpg','Mika becomes angry when she realizes that the relationship between Yūto and her sister is not progressing as well as she expected, so she forces Yūto out on a date with her to teach him tips to get in the right mood with Haruka. During their date, they go to a café, and catch a movie before running into Shiina, which makes Mika jealous. Mika drags Yūto to a kimono shop and the two are outfitted with brand-new kimonos before heading to the summer festival and watching the fireworks with Haruka, Hazuki, and Nanami who find them. Once school starts again, Shiina volunteers to be one of the organizing members for her class'' participation in the upcoming cultural festival, and Yūto gets dragged in to work with her.','[]','2008-08-28','51465');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('haruka-nogizakas-secret#9','haruka-nogizakas-secret',9,'I was so happy…','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/51466/original.jpg','Yūto''s class decides to do a cosplay café for the school festival, for which Yūto asks Haruka to go to Akihabara with him to see examples of cosplay costumes. Unknown to Yūto, Haruka had previously made a promise to her father to meet his client, however she decides to go with Yūto to Akihabara instead. Gentō becomes furious when he finds out and goes and finds them, but Akiho comes just in time to save them again. Haruka makes cookies and goes to give them to Yūto, but is shocked when she finds Yūto on top of Shiina at school.','[]','2008-09-04','51466');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('haruka-nogizakas-secret#10','haruka-nogizakas-secret',10,'I want to be with you…','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/51467/original.jpg','Haruka quickly leaves after seeing Yūto on top of Shiina, but when Yūto tries to explain the situation to her, Haruka says she understands, but ends up running back home. The next day during the school festival, Yūto finds Haruka to have apparently forgotten about yesterday, though Shiina is not so sure. Yūto confronts Haruka about yesterday again, but she tells him she does not want to hear what he has to say and runs off. Yūto runs into Hazuki as he is searching for Haruka, and she gives him so advice on how to move forward with Haruka. With Hazuki''s help, Yūto finds Haruka behind the gym where he apologizes for yesterday and assures her that he will not leave her. Afterwards, the two dance by the tune of the music box Yūto gave her previously as Nanami, Mika, and Hazuki watch from the bushes.','[]','2008-09-11','51467');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('haruka-nogizakas-secret#11','haruka-nogizakas-secret',11,'...Sorry For The Wait','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/51468/original.jpg','Mika calls Yūto late at night to invite him to Haruka''s birthday party on the evening of October 20. On the day of the celebration, Yūto goes to Akihabara to buy a gift and bumps into Nobunaga. After buying the gift, Yūto goes home and is fetched by Hazuki and Nanami to be taken to the party venue on an island far away together with Ruko and Yukari. On the island, Yūto meets up with Mika and Haruka. After meeting some of the guests, Yūto starts feeling insecure about his gift and social status.','[]','2008-09-18','51468');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('haruka-nogizakas-secret#12','haruka-nogizakas-secret',12,'It''s a Secret!','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/51469/original.jpg','The party has started and Yūto is dragged inside the party hall by Mika. While waiting for Yūto''s turn to present his gift, he again bumps into one of the guests and his gift is ridiculed. Yūto becomes insecure and is about to leave the party hall when an old man, who happens to be Haruka’s grandfather, helps Yūto regain back his confidence. Yūto runs back to Haruka and presents his gift. After the party, Yūto is with Haruka in her room, and Yūto then realizes that he was the one who gave the copy of the first issue of Innocent Smile to Haruka when they were kids.','[]','2008-09-25','51469');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('hanasaku-iroha-the-movie-home-sweet-home#1','hanasaku-iroha-the-movie-home-sweet-home',1,'Episode 1','66:00',3960,'','','[]',NULL,'87553');

